Same discount logic you already know. Count the WTFs out loud:
def proc(c, r, t2, o, a=False):
d = 0
if o == True:
if a == False:
d = 0
else:
if t2 == "strategic":
d = r * 0.15
else:
if t2 == "gold":
d = r * 0.10
else:
d = r * 0.05
else:
if t2 == "strategic":
d = r * 0.15
elif t2 == "gold":
